import {type AppFunctions} from '@sanity/sdk'
import {createAppFunctions} from '@sanity/sdk/_internal'
import {useContext, useMemo} from 'react'

import {AppFunctionsContext} from '../../context/AppFunctionsContext'
import {useClient} from '../client/useClient'

/**
 * Return the app's typed, authenticated functions. Types are generated by Sanity CLI.
 * Each call waits for the function's result and validates it against the generated contract.
 * @example
 * ```tsx
 * const functions = useFunctions()
 * const page = await functions.callWikipedia({timeout: 30_000})
 * ```
 * @public
 */
export function useFunctions(): AppFunctions {
  const binding = useContext(AppFunctionsContext)
  const client = useClient({apiVersion: '2026-06-15', scope: 'global'})
  const contracts = binding?.functions
  return useMemo(() => {
    if (!contracts) {
      throw new Error('App function contracts are missing. Build the app with Sanity CLI.')
    }
    return createAppFunctions(client, contracts)
  }, [client, contracts])
}
